-- Final check. Expected: 4044 businesses, all hidden; 4 lists; 3 life moments; 15 steps.
select
  (select count(*) from public.businesses) as businesses,
  (select count(*) from public.businesses where is_hidden) as hidden,
  (select count(*) from public.businesses where phone <> '' or cell <> '' or email <> '' or website <> '') as with_contact,
  (select count(*) from public.collections) as lists,
  (select count(*) from public.collection_items) as list_items,
  (select count(*) from public.journeys) as life_moments,
  (select count(*) from public.journey_steps) as steps;

